-- Easy single-word themes for younger players and warm-up rounds. Icons: Lucide (ISC), drawn in black,
-- the app recolors them.
INSERT INTO modes (id, name, icon, active, sort_order, status) VALUES
  (9, 'fun.mimesis.animals', 'data:image/svg+xml;base64,', 1, 1, 'free'),
  (12, 'fun.mimesis.actions', 'data:image/svg+xml;base64,', 1, 2, 'free'),
  (10, 'fun.mimesis.jobs', 'data:image/svg+xml;base64,', 1, 3, 'free'),
  (11, 'fun.mimesis.sports', 'data:image/svg+xml;base64,', 1, 4, 'free'),
  (13, 'fun.mimesis.food', 'data:image/svg+xml;base64,', 1, 5, 'free')
ON CONFLICT(id) DO UPDATE SET name = excluded.name, icon = excluded.icon, active = excluded.active, sort_order = excluded.sort_order, status = excluded.status;

-- Easy themes first, then the classic ones from easiest to hardest.
